@api_method
def get_industries(standard='zjh1', date=None):
    df = Engine.instance().basic_data_handler.get_industries(standard, date)
    try:
        if df.empty:
            return None
        else:
            dtype = convert_df_to_dtype(df)
            df_to_np = convert_dataframe_to_numpy(df, dtype)
            return df_to_np
    except AttributeError:
        system_log.error(get_traceback_message())
        return None
